class Checker:
    WORDS = {
        '0': 'zero',
        '1': 'one',
        '2': 'two',
        '3': 'three',
        '4': 'four',
        '5': 'five',
        '6': 'six',
        '7': 'seven',
        '8': 'eight',
        '9': 'nine',
    }

    def check(self, s, result):
        if not isinstance(result, str):
            return False
        if ''.join(sorted(result)) != result:
            return False
        if any(ch < '0' or ch > '9' for ch in result):
            return False
        from collections import Counter
        letters = Counter()
        for digit in result:
            letters.update(self.WORDS[digit])
        return letters == Counter(s)

